import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
all_keys = sorted(set(list(b.keys()) + list(a.keys())))
for k in all_keys:
    proj, tfm, pkg = k
    bv = b.get(k)
    av = a.get(k)
    if bv is None:
        changes.append((proj, tfm, pkg, '-', av, 'Added'))
    elif av is None:
        changes.append((proj, tfm, pkg, bv, '-', 'Removed'))
    elif bv != av:
        changes.append((proj, tfm, pkg, bv, av, 'Version changed'))
    else:
        unchanged.append((proj, tfm, pkg, av))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} ({c[1]}): {c[2]}  {c[3]} -> {c[4]}  [{c[5]}]')
else:
    print('None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]} ({u[1]}): {u[2]}  {u[3]}')
"

